      en: "A major border crossing and trading point between Vietnam and China's Yunnan province.",
      es: "Un importante paso fronterizo y punto comercial entre Vietnam y la provincia de Yunnan en China.",
      pt: "Uma importante passagem fronteiriça e ponto comercial entre o Vietnã e a província de Yunnan, na China.",
