    facts: {
      de: ["Spezialisiert auf landwirtschaftliche Exporte", "Tor zum zentralen Hochland"],
      hu: ["Mezőgazdasági exportra szakosodott", "Kapuja a Központi-felföldnek"],
      ro: ["Specializat pe exporturi agricole", "Poartă către Podișul Central"],
      en: ["Specializes in agricultural exports", "Gateway to the Central Highlands"],
      es: ["Especializado en exportaciones agrícolas", "Puerta de entrada a las tierras altas centrales"],
      pt: ["Especializado em exportações agrícolas", "Porta de entrada para o planalto central"],
      fr: ["Spécialisé dans les exportations agricoles", "Porte d'entrée des hauts plateaux du centre"],
    },
    descriptionAdvanced: {
      de: "Der Hafen von Quy Nhon in der Provinz Binh Dinh ist einer der zehn wichtigsten Seehäfen Vietnams und fungiert als vitales Tor für den Exportmarkt Zentralvietnams, Kambodschas und des südlichen Laos. Er liegt geschützt in der Bucht von Quy Nhon und zeichnet sich durch seine tiefen Gewässer aus, die den Zugang für große Containerschiffe ermöglichen. Der Hafen hat sich auf den Umschlag von Holzprodukten, Möbeln, Tapioka und Mineralien aus dem zentralen Hochland spezialisiert. In den letzten zehn Jahren wurden massive Investitionen in die Erweiterung der Kais und die Modernisierung der Kransysteme getätigt, um die Kapazität auf über 10 Millionen Tonnen pro Jahr zu steigern. Als Teil des maritimen Seidenstraßen-Projekts spielt Quy Nhon eine strategische Rolle in der regionalen Logistikkette. Die Nähe zur Autobahn und zum Schienennetz macht ihn zu einem attraktiven Standort für Industrieunternehmen, die sich in den umliegenden Wirtschaftszonen wie Nhon Hoi angesiedelt haben. Der Hafen ist somit ein entscheidender Treiber für die industrielle Entwicklung und den internationalen Handel in der Region.",
      hu: "Quy Nhon kikötője Binh Dinh tartományban Vietnám tíz legfontosabb tengeri kikötőjének egyike, és létfontosságú kapuként szolgál Közép-Vietnám, Kambodzsa és Dél-Laosz exportpiaca számára. A Quy Nhon-öböl védett területén fekszik, és mély vizei jellemzik, amelyek lehetővé teszik a nagy konténerszállító hajók belépését. A kikötő a központi felföldről származó fatermékek, bútorok, tápióka és ásványi anyagok rakodására specializálódott. Az elmúlt tíz évben hatalmas beruházások történtek a rakpartok bővítésébe és a darurendszerek modernizálásába, hogy a kapacitást évi 10 millió tonna fölé emeljék. A tengeri selyemút projekt részeként Quy Nhon stratégiai szerepet játszik a regionális logisztikai láncban. Az autópálya és a vasúthálózat közelsége vonzó helyszínné teszi az ipari vállalatok számára, amelyek a környező gazdasági övezetekben, például Nhon Hoi-ban telepedtek le. A kikötő tehát döntő mozgatórugója a régió ipari fejlődésének és nemzetközi kereskedelmének.",
      ro: "Portul Quy Nhon din provincia Binh Dinh este unul dintre cele mai importante zece porturi maritime din Vietnam și funcționează ca o poartă vitală pentru piața de export a Vietnamului Central, a Cambodgiei și a sudului Laosului. Este situat la adăpost în golful Quy Nhon și se caracterizează prin apele sale adânci care permit accesul navelor mari portcontainer. Portul este specializat în transbordarea produselor din lemn, mobilierului, tapiocăi și mineralelor din Podișul Central. În ultimii zece ani, au fost făcute investiții masive în extinderea cheiurilor și modernizarea sistemelor de macarale pentru a crește capacitatea la peste 10 milioane de tone pe an. Ca parte a proiectului Drumul Matasii Maritim, Quy Nhon joacă un rol strategic în lanțul logistic regional. Proximitatea față de autostradă și rețeaua feroviară îl face o locație atractivă pentru companiile industriale stabilite în zonele economice învecinate, cum ar fi Nhon Hoi. Portul este astfel un motor crucial pentru dezvoltarea industrială și comerțul internațional în regiune.",
      en: "The Port of Quy Nhon in Binh Dinh province is one of Vietnam's top ten seaports and serves as a vital gateway for the export markets of Central Vietnam, Cambodia, and Southern Laos. Sheltered within Quy Nhon Bay, it is characterized by deep waters that allow access for large container vessels. The port specializes in handling wood products, furniture, tapioca, and minerals originating from the Central Highlands. Over the past decade, massive investments have been made in extending berths and modernizing crane systems to increase capacity to over 10 million tons per year. As part of the maritime silk road initiative, Quy Nhon plays a strategic role in the regional logistics chain. Its proximity to the highway and railway network makes it an attractive location for industrial companies settled in surrounding economic zones like Nhon Hoi. The port is thus a critical driver for industrial development and international trade in the region.",
      es: "El puerto de Quy Nhơn es un elemento notable de la geografía y la cultura de Vietnam. Es un puerto estratégico en el centro del país, especializado en la carga de graneles como astillas de madera, mandioca y productos agrícolas. Especializado en exportaciones agrícolas. Puerta de entrada a las tierras altas centrales. Este sitio desempeña un papel en la economía de Vietnam, caracterizada por el cultivo de arroz y la exportación de café, textiles y electrónica. Como muchos lugares importantes de Vietnam, este sitio combina las peculiaridades regionales con el legado de una civilización milenaria y la época colonial francesa. Así, este lugar contribuye al perfil polifacético de Vietnam, desde el delta del Mekong hasta la bahía de Ha Long y las terrazas de arroz.",
      pt: "O porto de Quy Nhơn é um elemento notável da geografia e cultura do Vietnã. É um porto estratégico no centro do Vietnã, especializado na movimentação de cargas a granel como cavacos de madeira, mandioca e produtos agrícolas. Especializado em exportações agrícolas. Porta de entrada para o planalto central. Este local desempenha um papel na economia do Vietnã, caracterizada pelo cultivo de arroz e pela exportação de café, têxteis e eletrônicos. Como muitos lugares importantes no Vietnã, este local combina as peculiaridades regionais com a herança de uma civilização milenar e o período colonial francês. Assim, este lugar contribui para o perfil multifacetado do Vietnã — do Delta do Mekong à Baía de Ha Long e aos terraços de arroz.",
      fr: "Le port de Quy Nhơn est un élément remarquable de la géographie et de la culture vietnamiennes. Port stratégique du centre du Vietnam, il est spécialisé dans le traitement de marchandises en vrac telles que les copeaux de bois, le manioc et les produits agricoles. Spécialisé dans les exportations agricoles. Porte d'entrée des hauts plateaux du centre. Ce site joue un rôle dans l'économie du Vietnam, marquée par la riziculture et l'exportation de café, de textiles et d'électronique. Comme beaucoup de lieux importants au Vietnam, ce site allie les particularités régionales à l'héritage d'une civilisation millénaire et à l'époque coloniale française. Ainsi, ce lieu contribue au profil diversifié du Vietnam — du delta du Mékong à la baie d'Halong en passant par les rizières en terrasses.",
    },
